const voltage = Number(msg.payload);
if (!Number.isFinite(voltage) || voltage < 30 || voltage > 65) {
    node.warn("Ignoring invalid battery voltage: " + msg.payload);
    return null;
}

flow.set("batteryVoltage", voltage);
flow.set("batteryVoltageUpdatedAt", Date.now());
node.status({ fill: "green", shape: "dot", text: voltage.toFixed(2) + " V" });
return null;

const mode = Number(msg.payload);
if (!Number.isInteger(mode) || mode < 1 || mode > 4) {
    node.warn("Ignoring invalid Victron inverter mode: " + msg.payload);
    return null;
}

flow.set("inverterMode", mode);
flow.set("inverterModeUpdatedAt", Date.now());
node.status({ fill: mode === 2 ? "green" : "yellow", shape: "dot", text: "Mode " + mode });
return null;

const MAX_AGE_MS = 120000;
const now = Date.now();
const voltage = flow.get("batteryVoltage");
const voltageUpdatedAt = flow.get("batteryVoltageUpdatedAt");
const mode = flow.get("inverterMode");
const modeUpdatedAt = flow.get("inverterModeUpdatedAt");
const voltageAgeMs = now - voltageUpdatedAt;
const modeAgeMs = now - modeUpdatedAt;

msg.headers = { "Content-Type": "application/json" };
if (!Number.isFinite(voltage) || !Number.isFinite(voltageUpdatedAt) || voltageAgeMs < 0 || voltageAgeMs > MAX_AGE_MS || !Number.isInteger(mode) || mode < 1 || mode > 4 || !Number.isFinite(modeUpdatedAt) || modeAgeMs < 0 || modeAgeMs > MAX_AGE_MS) {
    msg.statusCode = 503;
    msg.payload = { error: "victron_data_unavailable" };
    return msg;
}

msg.statusCode = 200;
msg.payload = {
    sensors: {
        battery: { voltage: voltage },
        inverter: { mode: mode }
    },
    updatedAt: now
};
return msg;
